const c = document.getElementById('cv-demo')
const ctx = c.getContext('2d')

// 蓝色填充矩形
ctx.fillStyle = '#667eea'
ctx.fillRect(10, 10, 80, 50)

// 红色描边矩形
ctx.strokeStyle = '#ff375f'
ctx.lineWidth = 3
ctx.strokeRect(100, 10, 80, 50)

// 绿色圆形
ctx.fillStyle = '#34c759'
ctx.beginPath()
ctx.arc(50, 120, 35, 0, Math.PI * 2)
ctx.fill()

// 渐变文字
const grad = ctx.createLinearGradient(0, 0, 200, 0)
grad.addColorStop(0, '#ff375f')
grad.addColorStop(1, '#f59e0b')
ctx.fillStyle = grad
ctx.font = 'bold 24px sans-serif'
ctx.fillText('Canvas ✨', 100, 150)

const canvas = document.getElementById('cv-bounce')
const ctx = canvas.getContext('2d')

// 小球
let x = 50, y = 50
let vx = 2, vy = 1.5
const r = 15

function animate() {
  // 清除画布
  ctx.clearRect(0, 0, canvas.width, canvas.height)

  // 移动
  x += vx; y += vy

  // 碰撞检测（反弹）
  if (x + r > canvas.width || x - r < 0) vx *= -1
  if (y + r > canvas.height || y - r < 0) vy *= -1

  // 绘制小球
  ctx.beginPath()
  ctx.arc(x, y, r, 0, Math.PI * 2)
  const grad = ctx.createRadialGradient(x-3,y-3,2,x,y,r)
  grad.addColorStop(0, '#ff375f')
  grad.addColorStop(1, '#ff375f44')
  ctx.fillStyle = grad
  ctx.fill()

  requestAnimationFrame(animate)
}
animate()

// SVG 也可以用 JS 动态创建
const svgNS = 'http://www.w3.org/2000/svg'

function createCircle(cx, cy, r, color) {
  const circle = document.createElementNS(svgNS, 'circle')
  circle.setAttribute('cx', cx)
  circle.setAttribute('cy', cy)
  circle.setAttribute('r', r)
  circle.setAttribute('fill', color)
  return circle
}

